import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: ops","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_lib_stdlib/ops.md","filePath":"api/host/handl_plugin_lib_stdlib/ops.md"}`),a={name:`api/host/handl_plugin_lib_stdlib/ops.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_plugin_lib_stdlib &gt; ops</strong></p><h1 id="module-ops" tabindex="-1">Module: ops <a class="header-anchor" href="#module-ops" aria-label="Permalink to “Module: ops”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Modules</strong></p><ul><li><a href="#collections"><code>collections</code></a> - <code>collections</code> ops — native atoms for the collections package.</li><li><a href="#math"><code>math</code></a> - Rust <code>Function</code> impls for the <code>math</code> module — the handls (handlers)</li><li><a href="#strs"><code>strs</code></a> - Rust <code>Function</code> impls for the <code>str</code> module — the handls (handlers)</li><li><a href="#toml"><code>toml</code></a></li><li><a href="#yaml"><code>yaml</code></a></li></ul><hr><h2 id="module-collections" tabindex="-1">Module: collections <a class="header-anchor" href="#module-collections" aria-label="Permalink to “Module: collections”">​</a></h2><p><code>collections</code> ops — native atoms for the collections package.</p><p>Ported verbatim from the deleted <code>plugin-lib-collections</code> crate:</p><ul><li>[<code>seq</code>] — the shared sequential-container ops (<code>new</code>/<code>from</code>/ <code>to_array</code>). The <code>len</code>/<code>is_empty</code>/<code>push</code>/<code>pop</code>/<code>peek</code> surface and the end-parameterized members used by <code>vec</code>, <code>list</code>, <code>queue</code>, <code>stack</code>, and <code>deque</code> are now pure handl (see <code>handl-packages/collections/{vec,list,queue,stack,deque}.hnl</code>); the <code>pop</code>/<code>peek</code>/<code>dequeue</code>/<code>pop_*</code>/<code>peek_*</code> contract requires raising <code>collection is empty</code> on an empty structure, which is now expressible via the <code>error.raise</code> primitive (<code>handl-packages/error/error.hnl</code>). <code>new</code> stays native because it is nullary and <code>from</code> is a reserved word (it cannot be a record field); <code>to_array</code> stays grouped with them.</li><li>[<code>array</code>] — the <code>array.*</code> functional ops that take handl <strong>arrows</strong> (<code>take_while</code>/<code>drop_while</code>/<code>scan</code>/<code>foldr</code>/<code>find_*</code>): arrow arguments cannot cross the <code>HandlFunction</code> boundary, so they evaluate the serialized [<code>crate::function_value::FunctionValue</code>] body through <code>EvalContext::eval_expr</code> natively. The arrow-free <code>array.*</code> surface lives in <code>handl-packages/collections/array/index.hnl</code> as pure handl.</li><li>[<code>hash_map</code>] — the <code>hash_map.*</code> object ops. Native because handl has no object-key-iteration primitive (<code>merge</code>/<code>pick</code>/<code>omit</code>/<code>invert</code> need to enumerate a record&#39;s fields) and several members take arrow arguments.</li><li>[<code>hash_set</code>] — the <code>hash_set.*</code> set ops. Native because membership is keyed on a <em>serialized</em> value (<code>value_key</code>), which distinguishes <code>1</code> from <code>1.0</code> and differs from handl <code>==</code> (cross-numeric equality); a pure-handl port would change dedup semantics for mixed int/float inputs. <code>unique_by</code> additionally takes an arrow.</li></ul><p>[<code>collections_op_registry</code>] registers every op name under its full <code>module.fn</code> name (matching the former <code>build_registry</code>); the [<code>CollectionsModule</code>] aggregator preserves the former <code>collections</code>-module lookup shape (<code>vec.new</code>, <code>collections.vec.new</code>).</p><h2 id="module-math" tabindex="-1">Module: math <a class="header-anchor" href="#module-math" aria-label="Permalink to “Module: math”">​</a></h2><p>Rust <code>Function</code> impls for the <code>math</code> module — the handls (handlers) for the <code>op</code>/<code>handl</code> declarations in <code>math.hnl</code>.</p><p>All 62 functions are FFI atoms: they call <code>f64</code> methods or Rust arithmetic that cannot be expressed as pure handl arrows without losing the exact <code>TypeMismatch</code> error messages the tests rely on. The <code>op</code>/<code>handl</code> declaration form (ADR-0077 Phase 2) declares the interface in <code>math.hnl</code>; these impls provide the logic and are registered in an <a href="./handl_plugin_lib_handl::OpRegistry.html"><code>OpRegistry</code></a>.</p><h2 id="module-strs" tabindex="-1">Module: strs <a class="header-anchor" href="#module-strs" aria-label="Permalink to “Module: strs”">​</a></h2><p>Rust <code>Function</code> impls for the <code>str</code> module — the handls (handlers) for the <code>op</code>/<code>handl</code> declarations in <code>str.hnl</code>.</p><p>All 45 functions are FFI atoms: they call Rust <code>String</code>/<code>str</code> methods that cannot be expressed as pure handl arrows without losing the exact <code>TypeMismatch</code> error messages the tests rely on. The <code>op</code>/<code>handl</code> declaration form (ADR-0077 Phase 2) declares the interface in <code>str.hnl</code>; these impls provide the logic and are registered in an <a href="./handl_plugin_lib_handl::OpRegistry.html"><code>OpRegistry</code></a>.</p><h2 id="module-toml" tabindex="-1">Module: toml <a class="header-anchor" href="#module-toml" aria-label="Permalink to “Module: toml”">​</a></h2><h2 id="module-yaml" tabindex="-1">Module: yaml <a class="header-anchor" href="#module-yaml" aria-label="Permalink to “Module: yaml”">​</a></h2>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};